PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?inv ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (AVG(xsd:decimal(?sharpe)) AS ?avgSharpeRatio) (AVG(xsd:decimal(?vol)) AS ?avgVolatilityPct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:avgSharpeRatio ?sharpe ;
            wm:avgVolatilityPct ?vol .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      BIND( (xsd:decimal(?cv) - xsd:decimal(?cost)) AS ?gain )
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  FILTER( ?avgSharpeRatio < 0 && ?avgVolatilityPct > 10 && ?totalHoldingGain < 0 && ?netCashFlow < 1000000 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?combined_score WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmt)) AS ?net_cash_flow) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmt .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?raAmt)) AS ?total_rebalancing_amount) WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmt .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?newPct) - xsd:decimal(?currPct)) AS ?total_scenario_allocation_change) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?currPct .
    } GROUP BY ?investorId
  }

  BIND(
    COALESCE(?net_cash_flow, 0) +
    COALESCE(?total_rebalancing_amount, 0) +
    COALESCE(?total_scenario_allocation_change, 0)
    AS ?combined_score
  )
}
GROUP BY ?investorId ?investorName ?combined_score
ORDER BY DESC(?combined_score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (SUM(?netCashFlow) AS ?net_cash_flow) (AVG(?avgProgressPct) AS ?avg_progress_pct) (AVG(?avgRiskScore) AS ?avg_risk_score)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?inv ;
                wm:amount ?amount .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?progressPct .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?cash_flow_2025_amount ?avg_progress
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?invGoal ;
            wm:progressPct ?progressPct .
      ?invGoal wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cash_flow_2025_amount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?invCf ;
          wm:date ?date ;
          wm:amount ?amount .
      ?invCf wm:investorId ?investorId .
      FILTER(CONTAINS(LCASE(STR(?date)), "2025"))
    }
    GROUP BY ?investorId
  }

  FILTER(?avg_progress < 40)
}
ORDER BY DESC(?cash_flow_2025_amount) ?investorId
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  FILTER EXISTS {
    ?ra wm:rebalancingActionOfInvestor ?investor ;
        wm:action ?action .
    FILTER(LCASE(STR(?action)) = "sell")
  }

  FILTER EXISTS {
    ?sa wm:allocationOfInvestor ?investor ;
        wm:allocationPct ?allocationPct .
    FILTER(xsd:decimal(?allocationPct) > 35)
  }

  FILTER EXISTS {
    ?ph wm:heldByInvestor ?investor ;
        wm:returnsPct ?returnsPct .
    FILTER(xsd:decimal(?returnsPct) < 0)
  }

  FILTER EXISTS {
    ?phl wm:healthOfInvestor ?investor ;
         wm:diversificationScore ?divScore .
    FILTER(xsd:decimal(?divScore) < 30)
  }
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
