  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
                     (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
}
