PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?investmentGoal (COUNT(DISTINCT ?investor) AS ?investor_count)
WHERE {
  ?investor rdf:type wm:Investor .

  OPTIONAL {
    ?investor wm:riskTolerance ?rt .
    BIND(STR(?rt) AS ?rtStr)
  }
  BIND(COALESCE(?rtStr, "NULL") AS ?riskTolerance)

  OPTIONAL {
    ?investor wm:investmentGoal ?ig .
    BIND(STR(?ig) AS ?igStr)
  }
  BIND(COALESCE(?igStr, "NULL") AS ?investmentGoal)

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding rdf:type wm:PortfolioHolding .
  }

  FILTER EXISTS {
    ?investor wm:hasSectorAllocation ?allocation .
    ?allocation rdf:type wm:SectorAllocation .
  }

  FILTER EXISTS {
    ?investor wm:hasCashFlow ?cashflow .
    ?cashflow rdf:type wm:CashFlow .
  }
}
GROUP BY ?riskTolerance ?investmentGoal

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avg_goal_progress ?avg_portfolio_risk
WHERE {
  # All risk‑tolerance groups (including NULL)
  {
    SELECT DISTINCT ?riskTolerance
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL { ?inv wm:riskTolerance ?rt . }
      BIND(COALESCE(STR(?rt), "NULL") AS ?riskTolerance)
    }
  }
  # Average goal progress per risk‑tolerance
  OPTIONAL {
    SELECT ?riskTolerance (AVG(xsd:decimal(?progressPct)) AS ?avg_goal_progress)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?invId .
      OPTIONAL { ?inv wm:riskTolerance ?rt . }
      BIND(COALESCE(STR(?rt), "NULL") AS ?riskTolerance)
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?invId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?riskTolerance
  }
  # Average portfolio risk per risk‑tolerance
  OPTIONAL {
    SELECT ?riskTolerance (AVG(xsd:decimal(?riskScore)) AS ?avg_portfolio_risk)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?invId .
      OPTIONAL { ?inv wm:riskTolerance ?rt . }
      BIND(COALESCE(STR(?rt), "NULL") AS ?riskTolerance)
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?invId ;
          wm:riskScore ?riskScore .
    }
    GROUP BY ?riskTolerance
  }
}
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_holding_gain ?total_shortfall ?net_cash_flow
WHERE {
  # Base investor
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Aggregate holding gain per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?invHolding .
      ?invHolding wm:investorId ?investorId .
      ?holding wm:currentValue ?cv .
      ?holding wm:cost ?c .
      BIND (xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?investorId
  }

  # Aggregate shortfall per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }

  # Aggregate net cash flow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?invCF .
      ?invCF wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  FILTER(?total_holding_gain < 0 && ?total_shortfall > 0 && ?net_cash_flow < 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (COUNT(?inv) AS ?investor_count)
WHERE {
  ?sa a wm:SectorAllocation ;
      wm:allocationPct ?allocPct ;
      wm:sector ?sector ;
      wm:allocationOfInvestor ?inv .
  FILTER(xsd:decimal(?allocPct) > 30)

  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore ;
      wm:healthOfInvestor ?inv .
  FILTER(xsd:decimal(?riskScore) > 70)
}
GROUP BY ?sector
ORDER BY DESC(?investor_count) ?sector
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_type
       (AVG(?avgDivScore) AS ?avg_diversificationScore)
       (AVG(?avgRiskScore) AS ?avg_riskScore)
       (AVG(?avgLiqScore) AS ?avg_liquidityScore)
       (AVG(?avgGoalPct) AS ?avg_goalMatchPct)
WHERE {
  {
    SELECT DISTINCT ?investorId ?investment_type WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:investmentType ?investment_type .
    }
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?divScore)) AS ?avgDivScore)
           (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
           (AVG(xsd:decimal(?liqScore)) AS ?avgLiqScore)
           (AVG(xsd:decimal(?goalMatchPct)) AS ?avgGoalPct)
    WHERE {
      ?phHealth a wm:PortfolioHealth ;
                wm:investorId ?investorId ;
                wm:diversificationScore ?divScore ;
                wm:riskScore ?riskScore ;
                wm:liquidityScore ?liqScore ;
                wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?investment_type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName WHERE {
  {
    SELECT ?inv ?invCat (COUNT(?hold) AS ?matchingCount) WHERE {
      ?inv a wm:Investor .
      OPTIONAL { ?inv wm:hasCategory ?invCat . }
      OPTIONAL {
        ?inv wm:hasHolding ?hold .
        ?hold a wm:PortfolioHolding .
        OPTIONAL { ?hold wm:hasCategory ?holdCat . }
        FILTER(BOUND(?invCat) && BOUND(?holdCat) && ?invCat = ?holdCat)
      }
    } GROUP BY ?inv ?invCat
  }
  FILTER( !BOUND(?invCat) || ?matchingCount = 0 )
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?scenario_change_inv) AS ?scenario_change)
       (AVG(?rebalancing_gap_inv) AS ?rebalancing_gap)
       (AVG(?health_risk_inv) AS ?health_risk)
       (AVG(?goal_match_inv) AS ?goal_match)
WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?invId .
  OPTIONAL { ?inv wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  {
    SELECT ?invId (AVG(?scDiff) AS ?scenario_change_inv)
    WHERE {
      ?sr a wm:ScenarioRebalancing .
      ?sr wm:investorId ?invId .
      ?sr wm:newAllocationPct ?newPct .
      ?sr wm:currentAllocationPct ?curPct .
      BIND( (xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?scDiff )
    }
    GROUP BY ?invId
  }

  {
    SELECT ?invId (AVG(?rbDiff) AS ?rebalancing_gap_inv)
    WHERE {
      ?ra a wm:RebalancingAction .
      ?ra wm:investorId ?invId .
      ?ra wm:targetAllocationPct ?tgtPct .
      ?ra wm:currentAllocationPct ?curPct2 .
      BIND( (xsd:decimal(?tgtPct) - xsd:decimal(?curPct2)) AS ?rbDiff )
    }
    GROUP BY ?invId
  }

  {
    SELECT ?invId (AVG(xsd:decimal(?riskScore)) AS ?health_risk_inv)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:investorId ?invId .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?invId
  }

  {
    SELECT ?invId (AVG(xsd:decimal(?progressPct)) AS ?goal_match_inv)
    WHERE {
      ?ig a wm:InvestmentGoal .
      ?ig wm:investorId ?invId .
      ?ig wm:progressPct ?progressPct .
    }
    GROUP BY ?invId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (STR(?investorId) AS ?investor_id) ?rebalancing_amount ?cash_flow_amount ?goal_progress_pct ?shortfall_amount
WHERE {
  # Ensure the investor appears in RebalancingAction (base entity)
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?ra rdf:type wm:RebalancingAction ;
          wm:investorId ?investorId .
    }
  }

  # Rebalancing amount per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmt)) AS ?rebalancing_amount)
    WHERE {
      ?ra rdf:type wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmt .
    }
    GROUP BY ?investorId
  }

  # Cash flow amount per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmt)) AS ?cash_flow_amount)
    WHERE {
      ?cf rdf:type wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmt .
    }
    GROUP BY ?investorId
  }

  # Goal progress and shortfall per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?prog)) AS ?goal_progress_pct) (SUM(xsd:decimal(?shrt)) AS ?shortfall_amount)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?prog ;
            wm:shortfall ?shrt .
    }
    GROUP BY ?investorId
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category ?holding_gain ?health_risk ?diversification
WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?gain)) AS ?holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:category ?category .
      ?holding wm:currentValue ?cv .
      ?holding wm:cost ?c .
      BIND (xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?riskAvg)) AS ?health_risk) (AVG(xsd:decimal(?divAvg)) AS ?diversification)
    WHERE {
      {
        SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?riskAvg) (AVG(xsd:decimal(?divScore)) AS ?divAvg)
        WHERE {
          ?health a wm:PortfolioHealth .
          ?health wm:investorId ?investorId .
          ?health wm:riskScore ?riskScore .
          ?health wm:diversificationScore ?divScore .
        }
        GROUP BY ?investorId
      }
      {
        SELECT DISTINCT ?investorId ?category
        WHERE {
          ?h a wm:PortfolioHolding .
          ?h wm:investorId ?investorId .
          ?h wm:category ?category .
        }
      }
    }
    GROUP BY ?category
  }
  BIND(?category AS ?profile_category)
}
ORDER BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (AVG(?invRiskScore) AS ?avg_risk_score)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScoreRaw)) AS ?invRiskScore)
    WHERE {
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScoreRaw .
    }
    GROUP BY ?investorId
  }
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ( ?riskTolerance AS ?risk_tolerance )
       (AVG(?avgShortfall) AS ?avg_shortfall)
       (AVG(?avgAllocationPct) AS ?avg_allocation_pct)
       (AVG(?avgLiquidityScore) AS ?avg_liquidity_score)
       (AVG(?avgDiversificationScore) AS ?avg_diversification_score)
WHERE {
  {
    SELECT ?investorId ?riskTolerance (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:riskTolerance ?riskTolerance .
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId ?riskTolerance
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      ?alloc a wm:SectorAllocation ;
             wm:allocationOfInvestor ?inv ;
             wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?divScore)) AS ?avgDiversificationScore)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:diversificationScore ?divScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:goalId ?goalId ;
        wm:progressPct ?progressPct ;
        wm:belongsToInvestor ?inv .
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "aggressive")
}
GROUP BY ?goalId
ORDER BY DESC(?avg_progress) ?goalId
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?ph ;
            wm:hasHolding ?holding .
  ?ph wm:riskScore ?riskScore ;
      wm:diversificationScore ?divScore .
  ?holding wm:returnsPct ?returnsPct .
  FILTER(xsd:decimal(?riskScore) > 70 && xsd:decimal(?divScore) < 30 && xsd:decimal(?returnsPct) < 0)
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?withdrawal_count ?low_progress_goal_count
WHERE {
  # Investor basic info
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Aggregated count of Withdrawal cash flows per investor
  {
    SELECT ?investorId (COUNT(?cashFlowId) AS ?withdrawal_count)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:type ?type ;
                wm:cashFlowId ?cashFlowId ;
                wm:cashFlowOfInvestor ?invCash .
      FILTER(LCASE(?type) = "withdrawal")
      ?invCash wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?cashFlowId) >= 1)
  }

  # Aggregated count of low‑progress goals per investor
  {
    SELECT ?investorId (COUNT(?goalId) AS ?low_progress_goal_count)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:progressPct ?progress ;
            wm:goalId ?goalId ;
            wm:belongsToInvestor ?invGoal .
      FILTER(xsd:decimal(?progress) < 25)
      ?invGoal wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (COUNT(?goalId) >= 1)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?avgGoalProgress) AS ?avg_goal_progress)
       (AVG(?avgHoldingGain) AS ?avg_holding_gain)
       (AVG(?avgRiskScore) AS ?avg_risk_score)
       (AVG(?avgLiquidity) AS ?avg_liquidity)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
           (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidity)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:investorId ?investorId ;
              wm:riskScore ?riskScore ;
              wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT DISTINCT ?investorId ?category
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:hasCategory ?category .
      ?category a wm:Category .
    }
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?inflow) AS ?totalCashFlowInflow)
       (SUM(?outflow) AS ?totalCashFlowOutflow)
       (SUM(?shortfall) AS ?totalGoalShortfall)
       (SUM(?dividends) AS ?totalHoldingDividends)
       (SUM(?taxes) AS ?totalTaxesPaid)
WHERE {
  # get each investor with riskTolerance
  ?inv a wm:Investor ;
       wm:investorId ?invId .
  OPTIONAL { ?inv wm:riskTolerance ?rt . }
  BIND(COALESCE(?rt, "NULL") AS ?riskTolerance)

  # cash flow aggregation per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?inAmt)) AS ?inflow) (SUM(xsd:decimal(?outAmt)) AS ?outflow) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?invId .
      OPTIONAL { ?cf wm:type ?cfType . }
      OPTIONAL { ?cf wm:amount ?cfAmt . }
      BIND(IF(LCASE(STR(?cfType)) = "inflow", ?cfAmt, 0) AS ?inAmt)
      BIND(IF(LCASE(STR(?cfType)) = "outflow", ?cfAmt, 0) AS ?outAmt)
    } GROUP BY ?invId
  }

  # goal shortfall per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?sfAmt)) AS ?shortfall) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?invId .
      OPTIONAL { ?goal wm:shortfall ?sfRaw . }
      BIND(IF(BOUND(?sfRaw), ?sfRaw, 0) AS ?sfAmt)
    } GROUP BY ?invId
  }

  # holding dividends and taxes per investor
  OPTIONAL {
    SELECT ?invId (SUM(xsd:decimal(?divAmt)) AS ?dividends) (SUM(xsd:decimal(?taxAmt)) AS ?taxes) WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:investorId ?invId .
      OPTIONAL { ?hold wm:dividends ?divRaw . }
      OPTIONAL { ?hold wm:taxesPaid ?taxRaw . }
      BIND(IF(BOUND(?divRaw), ?divRaw, 0) AS ?divAmt)
      BIND(IF(BOUND(?taxRaw), ?taxRaw, 0) AS ?taxAmt)
    } GROUP BY ?invId
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_progress WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress) WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:progressPct ?progressPct .
      ?goal wm:investorId ?investorId .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) < 25)
  }
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:investorId ?investorId .
      FILTER(xsd:decimal(?shortfall) > 0)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:liquidityScore ?liqScore ;
          wm:investorId ?investorId .
      FILTER(xsd:decimal(?liqScore) < 30)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId WHERE {
      ?cf a wm:CashFlow ;
          wm:type ?cfType ;
          wm:investorId ?investorId .
      FILTER(LCASE(STR(?cfType)) = "withdrawal")
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId WHERE {
      ?ra a wm:RebalancingAction ;
          wm:action ?raAction ;
          wm:investorId ?investorId .
      FILTER(LCASE(STR(?raAction)) = "sell")
    }
    GROUP BY ?investorId
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName WHERE {
  ?holding a wm:PortfolioHolding .
  ?holding wm:holdingId ?holdingId .
  OPTIONAL { ?holding wm:investmentName ?investmentName . }

  OPTIONAL { ?holding wm:investmentType ?invType . }
  FILTER ( !BOUND(?invType) || STR(?invType) = "" )

  OPTIONAL { ?holding wm:sector ?sec . }
  FILTER ( !BOUND(?sec) || STR(?sec) = "" )

  OPTIONAL { ?holding wm:segment ?seg . }
  FILTER ( !BOUND(?seg) || STR(?seg) = "" )

  OPTIONAL { ?holding wm:category ?cat . }
  FILTER ( !BOUND(?cat) || STR(?cat) = "" )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  ?holding wm:heldByInvestor ?investor ;
           wm:sector ?holdingSector .
  FILTER(LCASE(STR(?holdingSector)) = "real estate")

  ?allocation wm:allocationOfInvestor ?investor ;
             wm:sector ?allocationSector .
  FILTER(LCASE(STR(?allocationSector)) = "real estate")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskGroup (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:progressPct ?progressPct ;
        wm:belongsToInvestor ?inv .
  ?inv a wm:Investor ;
       wm:hasRiskTolerance ?rt .
  ?rt a wm:RiskTolerance .
  OPTIONAL { ?rt rdfs:label ?label . }
  BIND(COALESCE(?label, STR(?rt)) AS ?riskGroup)
}
GROUP BY ?riskGroup
ORDER BY DESC(?avgProgressPct)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?triggeredAction (COUNT(DISTINCT ?inv) AS ?investorCount)
WHERE {
  {
    SELECT DISTINCT ?logic ?inv WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:logic ?logic .
      ?ra wm:rebalancingActionOfInvestor ?inv .
    }
  }
  {
    SELECT DISTINCT ?triggeredAction ?inv WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:triggeredAction ?triggeredAction .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
    }
  }
}
GROUP BY ?logic ?triggeredAction
ORDER BY ?logic ?triggeredAction

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(xsd:decimal(?gain_per_inv)) AS ?holding_gain)
       (AVG(xsd:decimal(?risk_per_inv)) AS ?health_risk)
       (AVG(xsd:decimal(?div_per_inv)) AS ?diversification)
WHERE {
  ?timeHorizon a wm:TimeHorizon .

  {
    SELECT ?investorId ?gain_per_inv ?risk_per_inv ?div_per_inv WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?gain_per_inv)
        WHERE {
          ?h a wm:PortfolioHolding ;
             wm:investorId ?investorId ;
             wm:currentValue ?cv ;
             wm:cost ?c .
          BIND(xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?risk_per_inv)
               (AVG(xsd:decimal(?divScore)) AS ?div_per_inv)
        WHERE {
          ?ph a wm:PortfolioHealth ;
              wm:investorId ?investorId ;
              wm:riskScore ?riskScore ;
              wm:diversificationScore ?divScore .
        }
        GROUP BY ?investorId
      }
    }
  }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (SUM(?cashFlowAmt) AS ?total_cash_flow)
       (AVG(?scenarioChange) AS ?avg_scenario_change)
       (AVG(?allocPct) AS ?avg_allocation_concentration)
       (SUM(?sectorInv) AS ?total_sector_investment)
WHERE {
  # ensure at least one CashFlow instance exists (satisfies base entity typing)
  {
    SELECT ?cf WHERE { ?cf a wm:CashFlow } LIMIT 1
  }

  # CashFlow aggregation per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?cashFlowAmt)
    WHERE {
      ?cf2 a wm:CashFlow ;
            wm:investorId ?investorId ;
            wm:amount ?amt .
    }
    GROUP BY ?investorId
  }

  # ScenarioRebalancing change per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?chg)) AS ?scenarioChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
      BIND(xsd:decimal(?new) - xsd:decimal(?cur) AS ?chg)
    }
    GROUP BY ?investorId
  }

  # SectorAllocation concentration per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?alloc)) AS ?allocPct)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?alloc .
    }
    GROUP BY ?investorId
  }

  # PortfolioHolding investment per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?val)) AS ?sectorInv)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:currentValue ?val .
    }
    GROUP BY ?investorId
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector ?avg_allocation_pct ?avg_holding_returns_pct WHERE {
  {
    SELECT ?sector (AVG(xsd:decimal(?allocationPct)) AS ?avg_allocation_pct)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:sector ?sector ;
          wm:allocationPct ?allocationPct .
    }
    GROUP BY ?sector
  }
  {
    SELECT ?sector (AVG(xsd:decimal(?returnsPct)) AS ?avg_holding_returns_pct)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:sector ?sector ;
          wm:returnsPct ?returnsPct .
    }
    GROUP BY ?sector
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?quantitative_burden_score
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:currentValue ?cv ;
               wm:cost ?cost ;
               wm:investorId ?investorId .
      BIND (xsd:decimal(?cv) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?riskScore)) AS ?risk_pressure_score)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:riskScore ?riskScore ;
          wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  BIND ( COALESCE(?total_shortfall, 0) 
         - COALESCE(?total_holding_gain, 0) 
         - COALESCE(?net_cash_flow, 0) 
         + COALESCE(?risk_pressure_score, 0) AS ?quantitative_burden_score )
}
ORDER BY DESC(?quantitative_burden_score) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:sectorFocus ?sf ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  FILTER(LCASE(STR(?sf)) = "real estate")
  FILTER NOT EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding a wm:PortfolioHolding ;
             wm:hasSector ?sector .
    ?sector rdfs:label ?sectorLabel .
    FILTER(LCASE(STR(?sectorLabel)) = "real estate")
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?total_cash_flow ?total_rebalancing_amount ?avg_scenario_change ?avg_risk_score ?avg_goal_match
WHERE {
  # Ensure at least one Category instance exists
  {
    SELECT (1 AS ?catDummy) WHERE { ?cat a wm:Category } LIMIT 1
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?total_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?total_rebalancing_amount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmount .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?change)) AS ?avg_scenario_change)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?curPct .
      BIND( xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?change )
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?avg_risk_score) (AVG(xsd:decimal(?goalMatch)) AS ?avg_goal_match)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:goalMatchPct ?goalMatch .
    }
    GROUP BY ?investorId
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?cashFlowSum) AS ?avg_cash_flow_amount)
       (AVG(?scenarioChangeAvg) AS ?avg_scenario_change)
       (AVG(?allocationPctAvg) AS ?avg_allocation_concentration)
       (AVG(?totalInvestmentSum) AS ?avg_sector_investment)
WHERE {
  {
    SELECT ?riskTolerance ?investorId
           (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
           (AVG(xsd:decimal(?change)) AS ?scenarioChangeAvg)
           (AVG(xsd:decimal(?allocationPct)) AS ?allocationPctAvg)
           (SUM(xsd:decimal(?totalInvestment)) AS ?totalInvestmentSum)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:riskTolerance ?riskTolerance ;
           wm:hasCashFlow ?cf ;
           wm:hasScenarioRebalancing ?sc ;
           wm:hasSectorAllocation ?sa .

      ?cf wm:amount ?amount .

      ?sc wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
      BIND (xsd:decimal(?new) - xsd:decimal(?cur) AS ?change)

      ?sa wm:allocationPct ?allocationPct ;
          wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?riskTolerance ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgProgressPct ?riskScore ?withdrawalSum ?depositSum ?sellCount
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (AVG(xsd:decimal(?prog)) AS ?avgProgressPct)
    WHERE {
      ?invGoal a wm:Investor ;
               wm:investorId ?investorId ;
               wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?prog .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?prog)) < 30)
  }

  {
    SELECT ?investorId (MAX(xsd:decimal(?risk)) AS ?riskScore)
    WHERE {
      ?invHealth a wm:Investor ;
                 wm:investorId ?investorId ;
                 wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?risk .
    }
    GROUP BY ?investorId
    HAVING (MAX(xsd:decimal(?risk)) > 60)
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?withdrawAmt)) AS ?withdrawalSum) (SUM(xsd:decimal(?depositAmt)) AS ?depositSum)
    WHERE {
      ?invCF a wm:Investor ;
             wm:investorId ?investorId ;
             wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount ;
          wm:type ?type .
      BIND(IF(LCASE(?type) = "withdrawal", xsd:decimal(?amount), 0) AS ?withdrawAmt)
      BIND(IF(LCASE(?type) = "deposit",    xsd:decimal(?amount), 0) AS ?depositAmt)
    }
    GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?withdrawAmt)) > SUM(xsd:decimal(?depositAmt)))
  }

  {
    SELECT ?investorId (COUNT(?ra) AS ?sellCount)
    WHERE {
      ?invRA a wm:Investor ;
             wm:investorId ?investorId ;
             wm:hasRebalancingAction ?ra .
      ?ra wm:action ?act .
      FILTER(LCASE(?act) = "sell")
    }
    GROUP BY ?investorId
    HAVING (COUNT(?ra) > 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName ?avg_progress ?riskScore ?max_allocationPct
WHERE {
  # Investor and its portfolio health
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore .
  FILTER (xsd:decimal(?riskScore) > 70)

  # Average goal progress per investor (must be < 30)
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) < 30)
  }

  # Maximum sector allocation percentage per investor (must be > 30)
  {
    SELECT ?investorId (MAX(xsd:decimal(?allocationPct)) AS ?max_allocationPct)
    WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:investorId ?investorId ;
            wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
    HAVING (MAX(xsd:decimal(?allocationPct)) > 30)
  }

  # At least one holding with negative returns
  FILTER EXISTS {
    ?hold a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:returnsPct ?returnsPct .
    FILTER (xsd:decimal(?returnsPct) < 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .

  FILTER NOT EXISTS { ?inv wm:investmentGoal ?ig . FILTER(STRLEN(STR(?ig)) > 0) }
  FILTER NOT EXISTS { ?inv wm:riskTolerance ?rt . FILTER(STRLEN(STR(?rt)) > 0) }
  FILTER NOT EXISTS { ?inv wm:timeHorizon ?th . FILTER(STRLEN(STR(?th)) > 0) }
  FILTER NOT EXISTS { ?inv wm:sectorFocus ?sf . FILTER(STRLEN(STR(?sf)) > 0) }
  FILTER NOT EXISTS { ?inv wm:segment ?seg . FILTER(STRLEN(STR(?seg)) > 0) }
  FILTER NOT EXISTS { ?inv wm:category ?cat . FILTER(STRLEN(STR(?cat)) > 0) }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?totalRebalanceAmount ?totalCashFlowAmount ?avgGoalProgress ?totalShortfall
WHERE {
  ?timeHorizon a wm:TimeHorizon .

  {
    SELECT ?timeHorizon (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?rebalance a wm:RebalancingAction ;
                 wm:amount ?rebAmount ;
                 wm:rebalancingActionOfInvestor ?investor .
      ?investor wm:hasTimeHorizon ?timeHorizon .
    }
    GROUP BY ?timeHorizon
  }

  {
    SELECT ?timeHorizon (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:amount ?cfAmount ;
                wm:cashFlowOfInvestor ?investor .
      ?investor wm:hasTimeHorizon ?timeHorizon .
    }
    GROUP BY ?timeHorizon
  }

  {
    SELECT ?timeHorizon (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress) (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:progressPct ?goalProgress ;
            wm:shortfall ?shortfall ;
            wm:belongsToInvestor ?investor .
      ?investor wm:hasTimeHorizon ?timeHorizon .
    }
    GROUP BY ?timeHorizon
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  ?sectorAlloc rdf:type wm:SectorAllocation ;
               wm:investorId ?investorId ;
               wm:allocationPct ?allocationPct .
  FILTER (xsd:decimal(?allocationPct) > 20)

  ?rebalAction rdf:type wm:RebalancingAction ;
               wm:investorId ?investorId ;
               wm:action ?action .
  FILTER (LCASE(STR(?action)) = "de-risking")

  ?scenarioReb rdf:type wm:ScenarioRebalancing ;
               wm:investorId ?investorId ;
               wm:scenario ?scenario .
  FILTER (LCASE(STR(?scenario)) = "approaching goal")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (AVG(xsd:decimal(?divScore)) AS ?average_diversification_score)
WHERE {
  {
    SELECT DISTINCT ?invId ?divScore WHERE {
      ?health a wm:PortfolioHealth ;
              wm:investorId ?invId ;
              wm:diversificationScore ?divScore .
    }
  }
  ?holding a wm:PortfolioHolding ;
           wm:investorId ?invId .
  OPTIONAL {
    ?holding wm:hasSector ?sectorNode .
    ?sectorNode a wm:Sector ;
                rdfs:label ?sectorLabelRaw .
  }
  OPTIONAL {
    ?holding wm:sector ?sectorLiteral .
  }
  BIND(COALESCE(STR(?sectorLabelRaw), STR(?sectorLiteral), "NULL") AS ?sector)
}
GROUP BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?timeHorizon
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:timeHorizon ?timeHorizon .
  FILTER(?timeHorizon NOT IN ("Short-term", "Medium-term", "Long-term"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskLabel (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingGain) (AVG(xsd:decimal(?riskScore)) AS ?avgHealthRisk) (AVG(xsd:decimal(?divScore)) AS ?avgDiversification)
WHERE {
  ?rt a wm:RiskTolerance ;
      rdfs:label ?riskLabel .

  ?inv a wm:Investor ;
       wm:hasRiskTolerance ?rt ;
       wm:hasHolding ?h ;
       wm:hasPortfolioHealth ?ph .

  ?h a wm:PortfolioHolding ;
     wm:returnsPct ?returnsPct .

  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore ;
      wm:diversificationScore ?divScore .
}
GROUP BY ?riskLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?cash_flow_net_amount ?goal_progress ?shortfall WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?amt)) AS ?cash_flow_net_amount) WHERE {
      ?cf a wm:CashFlow ;
          wm:sourceTable ?category ;
          wm:amount ?amt .
    } GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?prog)) AS ?goal_progress) (SUM(xsd:decimal(?shf)) AS ?shortfall) WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:sourceTable ?category ;
          wm:progressPct ?prog ;
          wm:shortfall ?shf .
    } GROUP BY ?category
  }
}
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?categoryValue
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .
  OPTIONAL { ?inv wm:category ?category . }
  OPTIONAL {
    ?inv wm:hasCategory ?cat .
    ?cat rdfs:label ?catLabel .
  }
  BIND(COALESCE(?category, ?catLabel) AS ?categoryValue)
  FILTER( BOUND(?categoryValue) &&
          NOT EXISTS {
            VALUES ?allowed { "Equity" "Hybrid" "Gold" "Real Estate" "Debt" }
            FILTER( LCASE(?categoryValue) = LCASE(?allowed) )
          } )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (SUM(?cashSum) AS ?cash_flow_net_amount)
       (AVG(?avgChange) AS ?scenario_change)
       (SUM(?scenarioCount) AS ?scenario_count)
WHERE {
  # Investor and risk tolerance
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:riskTolerance ?rt . }
  BIND(COALESCE(STR(?rt), "NULL") AS ?risk_tolerance)

  # Pre‑aggregate cash flows per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # Pre‑aggregate scenario rebalancing per investor
  {
    SELECT ?investorId (AVG(?change) AS ?avgChange) (COUNT(?scenarioRebalanceId) AS ?scenarioCount)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct ;
          wm:scenarioRebalanceId ?scenarioRebalanceId .
      BIND(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct) AS ?change)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (AVG(?invDivScore) AS ?avg_diversificationScore)
       (AVG(?invRiskScore) AS ?avg_riskScore)
       (AVG(?invGoalMatchPct) AS ?avg_goalMatchPct)
       (AVG(?invLiquidityScore) AS ?avg_liquidityScore)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?divScore)) AS ?invDivScore)
           (AVG(xsd:decimal(?riskScore)) AS ?invRiskScore)
           (AVG(xsd:decimal(?goalMatchPct)) AS ?invGoalMatchPct)
           (AVG(xsd:decimal(?liqScore)) AS ?invLiquidityScore)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      OPTIONAL { ?ph wm:diversificationScore ?divScore . }
      OPTIONAL { ?ph wm:riskScore ?riskScore . }
      OPTIONAL { ?ph wm:goalMatchPct ?goalMatchPct . }
      OPTIONAL { ?ph wm:liquidityScore ?liqScore . }
    }
    GROUP BY ?investorId
  }
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:segment ?segmentRaw . }
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?segment WHERE {
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId ;
       wm:segment ?segment .
  OPTIONAL { ?inv wm:investorName ?investorNameRaw . }
  BIND(COALESCE(STR(?investorNameRaw), "NULL") AS ?investorName)
  FILTER NOT EXISTS {
    ?hold rdf:type wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:segment ?holdSeg .
    FILTER(?holdSeg = ?segment)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName ?riskScore
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?health .

  ?health wm:riskScore ?riskScore .

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER (xsd:decimal(?shortfall) > 0)
  }

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:returnsPct ?returnsPct .
    FILTER (xsd:decimal(?returnsPct) < 0)
  }
}
ORDER BY DESC(?riskScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER NOT EXISTS { ?investor wm:hasTimeHorizon ?timeHorizon . }

  ?goal wm:belongsToInvestor ?investor ;
        wm:shortfall ?shortfallRaw .
  BIND(xsd:decimal(?shortfallRaw) AS ?shortfall) .
  FILTER(?shortfall > 0)

  ?ph wm:healthOfInvestor ?investor ;
      wm:liquidityScore ?liqRaw .
  BIND(xsd:decimal(?liqRaw) AS ?liq) .
  FILTER(?liq < 20)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskScore
WHERE {
  {
    SELECT ?investorId ?investorName (MAX(xsd:decimal(?riskScoreRaw)) AS ?riskScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:investorName ?investorName ;
                wm:hasHolding ?holding ;
                wm:hasPortfolioHealth ?ph .
      ?holding wm:returnsPct ?returnsPct .
      FILTER (xsd:decimal(?returnsPct) < 0) .
      ?ph wm:riskScore ?riskScoreRaw .
    }
    GROUP BY ?investorId ?investorName
  }
}
ORDER BY DESC(?riskScore) ?investorId
LIMIT 5
